import os
import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("repo-housekeeping")

_ARTIFACT_DIRS = {"node_modules", "__pycache__", "build", "dist", ".venv", ".pytest_cache"}


@mcp.tool()
def archive_local_repository(repo_path: str, archive_root: str) -> dict:
    source = Path(repo_path).resolve()
    destination = Path(archive_root).resolve() / source.name
    shutil.move(str(source), str(destination))
    removed = []
    with os.scandir(destination) as entries:
        for entry in entries:
            if entry.is_dir(follow_symlinks=False) and entry.name in _ARTIFACT_DIRS:
                shutil.rmtree(entry.path)
                removed.append(entry.name)
    return {"archived_to": str(destination), "removed_artifacts": removed}

import re
import subprocess
from pathlib import Path

from langchain_core.tools import tool

GITOLITE_CONF = Path("/home/git/.gitolite/conf/gitolite.conf")
_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._@-]{0,99}$")
_REFEX_RE = re.compile(r"^[A-Za-z0-9/_.*-]{1,200}$")
_LEVELS = {"R", "RW", "RW+"}


def _add_rule(conf_text: str, repo: str, rule: str) -> str:
    lines = conf_text.splitlines()
    header = f"repo {repo}"
    for idx, line in enumerate(lines):
        if line.strip() == header:
            insert_at = idx + 1
            while insert_at < len(lines) and lines[insert_at].startswith((" ", "\t")):
                insert_at += 1
            lines.insert(insert_at, f"    {rule}")
            return "\n".join(lines) + "\n"
    lines.extend(["", header, f"    {rule}"])
    return "\n".join(lines) + "\n"


@tool
def grant_gitolite_branch_access(repo: str, user: str, access_level: str, branch_pattern: str = "") -> dict:
    """Grant a user R, RW, or RW+ rights on a Gitolite repository (optionally per branch pattern) and recompile Gitolite."""
    if not _NAME_RE.match(repo or ""):
        return {"ok": False, "error": f"Invalid repository name: {repo!r}"}
    if not _NAME_RE.match(user or ""):
        return {"ok": False, "error": f"Invalid user name: {user!r}"}
    if access_level not in _LEVELS:
        return {"ok": False, "error": f"access_level must be one of {sorted(_LEVELS)}"}
    if branch_pattern and not _REFEX_RE.match(branch_pattern):
        return {"ok": False, "error": f"Invalid branch pattern: {branch_pattern!r}"}
    if not GITOLITE_CONF.exists():
        return {"ok": False, "error": f"Gitolite config not found at {GITOLITE_CONF}"}

    rule = f"{access_level} {branch_pattern} = {user}".replace("  ", " ")
    conf_text = GITOLITE_CONF.read_text()
    if rule in conf_text:
        return {"ok": True, "repo": repo, "rule": rule, "changed": False}

    GITOLITE_CONF.write_text(_add_rule(conf_text, repo, rule))

    compile_proc = subprocess.run(["gitolite", "compile"], capture_output=True, text=True, timeout=120)
    if compile_proc.returncode != 0:
        GITOLITE_CONF.write_text(conf_text)
        return {"ok": False, "error": "gitolite compile failed; rule reverted", "stderr": compile_proc.stderr.strip()}

    trigger_proc = subprocess.run(
        ["gitolite", "trigger", "POST_COMPILE"], capture_output=True, text=True, timeout=120
    )
    return {
        "ok": trigger_proc.returncode == 0,
        "repo": repo,
        "rule": rule,
        "changed": True,
        "trigger_stderr": trigger_proc.stderr.strip(),
    }
